insert into public.daily_verses (sort, reference, text) values
  (1, 'Mateo 4:4', 'Escrito está: “No solo de pan vive el hombre, sino de toda palabra que sale de la boca de Dios”.'),
  (2, 'Salmo 1:1-2', 'Dichoso el hombre que no sigue el consejo de los malvados, ni se detiene en la senda de los pecadores, sino que en la ley del Señor se deleita, y día y noche medita en ella.'),
  (3, 'Hechos 1:8', 'Pero, cuando venga el Espíritu Santo sobre ustedes, recibirán poder y serán mis testigos.'),
  (4, 'Proverbios 1:7', 'El temor del Señor es el principio del conocimiento; los necios desprecian la sabiduría y la disciplina.'),
  (5, 'Mateo 5:3', 'Dichosos los pobres en espíritu, porque el reino de los cielos les pertenece.'),
  (6, 'Salmo 1:3', 'Es como el árbol plantado a la orilla de un río que, cuando llega su tiempo, da fruto y sus hojas jamás se marchitan. ¡Todo cuanto hace prospera!'),
  (7, 'Hechos 2:42', 'Se mantenían firmes en la enseñanza de los apóstoles, en la comunión, en el partimiento del pan y en la oración.'),
  (8, 'Mateo 5:4', 'Dichosos los que lloran, porque serán consolados.'),
  (9, 'Proverbios 2:6', 'Porque el Señor da la sabiduría; conocimiento y ciencia brotan de sus labios.'),
  (10, 'Salmo 3:3', 'Pero tú, Señor, me rodeas cual escudo; tú eres mi gloria; ¡tú mantienes en alto mi cabeza!'),
  (11, 'Hechos 4:12', 'De hecho, en ningún otro hay salvación, porque no hay bajo el cielo otro nombre dado a los hombres mediante el cual podamos ser salvos.'),
  (12, 'Mateo 5:5', 'Dichosos los humildes, porque recibirán la tierra como herencia.'),
  (13, 'Salmo 4:8', 'En paz me acuesto y me duermo, porque solo tú, Señor, me haces vivir confiado.'),
  (14, 'Mateo 5:6', 'Dichosos los que tienen hambre y sed de justicia, porque serán saciados.'),
  (15, 'Hechos 16:31', 'Cree en el Señor Jesús; así tú y tu familia serán salvos.'),
  (16, 'Proverbios 3:3', 'Que nunca te abandonen el amor y la verdad: llévalos siempre alrededor de tu cuello y escríbelos en el libro de tu corazón.'),
  (17, 'Mateo 5:7', 'Dichosos los compasivos, porque serán tratados con compasión.'),
  (18, 'Salmo 5:3', 'Por la mañana, Señor, escuchas mi clamor; por la mañana te presento mis ruegos, y quedo a la espera de tu respuesta.'),
  (19, 'Hechos 17:28', 'Puesto que en él vivimos, nos movemos y existimos.'),
  (20, 'Mateo 5:8', 'Dichosos los de corazón limpio, porque ellos verán a Dios.'),
  (21, 'Salmo 9:1', 'Quiero alabarte, Señor, con todo el corazón, y contar todas tus maravillas.'),
  (22, 'Proverbios 3:5', 'Confía en el Señor de todo corazón, y no en tu propia inteligencia.'),
  (23, 'Hechos 20:35', 'Hay más dicha en dar que en recibir.'),
  (24, 'Mateo 5:9', 'Dichosos los que trabajan por la paz, porque serán llamados hijos de Dios.'),
  (25, 'Salmo 9:10', 'En ti confían los que conocen tu nombre, porque tú, Señor, jamás abandonas a los que te buscan.'),
  (26, 'Romanos 1:16', 'A la verdad, no me avergüenzo del evangelio, pues es poder de Dios para la salvación de todos los que creen.'),
  (27, 'Mateo 5:14', 'Ustedes son la luz del mundo. Una ciudad en lo alto de una colina no puede esconderse.'),
  (28, 'Proverbios 3:6', 'Reconócelo en todos tus caminos, y él allanará tus sendas.'),
  (29, 'Mateo 5:16', 'Hagan brillar su luz delante de todos, para que ellos puedan ver las buenas obras de ustedes y alaben al Padre que está en el cielo.'),
  (30, 'Salmo 16:8', 'Siempre tengo presente al Señor; con él a mi derecha, nada me hará caer.'),
  (31, 'Romanos 5:1', 'En consecuencia, ya que hemos sido justificados mediante la fe, tenemos paz con Dios por medio de nuestro Señor Jesucristo.'),
  (32, 'Mateo 5:44', 'Pero yo les digo: Amen a sus enemigos y oren por quienes los persiguen.'),
  (33, 'Salmo 16:11', 'Me has dado a conocer la senda de la vida; me llenarás de alegría en tu presencia, y de dicha eterna a tu derecha.'),
  (34, 'Romanos 5:5', 'Dios ha derramado su amor en nuestro corazón por el Espíritu Santo que nos ha dado.'),
  (35, 'Proverbios 3:9', 'Honra al Señor con tus riquezas y con los primeros frutos de tus cosechas.'),
  (36, 'Mateo 6:6', 'Pero tú, cuando te pongas a orar, entra en tu cuarto, cierra la puerta y ora a tu Padre, que está en lo secreto. Así tu Padre, que ve lo que se hace en secreto, te recompensará.'),
  (37, 'Salmo 18:2', 'El Señor es mi roca, mi amparo, mi libertador; es mi Dios, el peñasco en que me refugio.'),
  (38, 'Romanos 5:8', 'Pero Dios demuestra su amor por nosotros en esto: en que cuando todavía éramos pecadores, Cristo murió por nosotros.'),
  (39, 'Mateo 6:21', 'Porque donde esté tu tesoro, allí estará también tu corazón.'),
  (40, 'Proverbios 3:27', 'No niegues un favor a quien te lo pida, si en tu mano está el otorgarlo.'),
  (41, 'Salmo 19:1', 'Los cielos cuentan la gloria de Dios, el firmamento proclama la obra de sus manos.'),
  (42, 'Mateo 6:33', 'Más bien, busquen primeramente el reino de Dios y su justicia, y todas estas cosas les serán añadidas.'),
  (43, 'Romanos 6:23', 'Porque la paga del pecado es muerte, mientras que la dádiva de Dios es vida eterna en Cristo Jesús, nuestro Señor.'),
  (44, 'Mateo 6:34', 'Por lo tanto, no se angustien por el mañana, el cual tendrá sus propios afanes. Cada día tiene ya sus problemas.'),
  (45, 'Salmo 19:14', 'Sean, pues, aceptables ante ti mis palabras y mis pensamientos, oh Señor, roca mía y redentor mío.'),
  (46, 'Romanos 8:1', 'Por lo tanto, ya no hay ninguna condenación para los que están unidos a Cristo Jesús.'),
  (47, 'Proverbios 4:7', 'La sabiduría es lo primero. ¡Adquiere sabiduría! Por sobre todas las cosas, adquiere discernimiento.'),
  (48, 'Mateo 7:7', 'Pidan, y se les dará; busquen, y encontrarán; llamen, y se les abrirá.'),
  (49, 'Salmo 23:1', 'El Señor es mi pastor, nada me falta.'),
  (50, 'Romanos 8:18', 'De hecho, considero que en nada se comparan los sufrimientos actuales con la gloria que habrá de revelarse en nosotros.'),
  (51, 'Mateo 7:12', 'Así que en todo traten ustedes a los demás tal y como quieren que ellos los traten a ustedes.'),
  (52, 'Proverbios 4:18', 'La senda de los justos se asemeja a los primeros albores de la aurora: su esplendor va en aumento hasta que el día alcanza su plenitud.'),
  (53, 'Salmo 23:2-3', 'En verdes pastos me hace descansar. Junto a tranquilas aguas me conduce; me infunde nuevas fuerzas.'),
  (54, 'Romanos 8:28', 'Ahora bien, sabemos que Dios dispone todas las cosas para el bien de quienes lo aman, los que han sido llamados de acuerdo con su propósito.'),
  (55, 'Mateo 7:24', 'Por tanto, todo el que me oye estas palabras y las pone en práctica es como un hombre prudente que construyó su casa sobre la roca.'),
  (56, 'Salmo 23:4', 'Aun si voy por valles tenebrosos, no temo peligro alguno, porque tú estás a mi lado.'),
  (57, 'Mateo 9:37-38', 'La cosecha es abundante, pero son pocos los obreros. Pídanle, por tanto, al Señor de la cosecha que envíe obreros a su campo.'),
  (58, 'Romanos 8:31', '¿Qué diremos frente a esto? Si Dios está de nuestra parte, ¿quién puede estar en contra nuestra?'),
  (59, 'Proverbios 4:23', 'Por sobre todas las cosas cuida tu corazón, porque de él mana la vida.'),
  (60, 'Mateo 10:31', 'Así que no tengan miedo; ustedes valen más que muchos gorriones.'),
  (61, 'Salmo 23:6', 'La bondad y el amor me seguirán todos los días de mi vida; y en la casa del Señor habitaré para siempre.'),
  (62, 'Romanos 8:37', 'Sin embargo, en todo esto somos más que vencedores por medio de aquel que nos amó.'),
  (63, 'Mateo 11:28', 'Vengan a mí todos ustedes que están cansados y agobiados, y yo les daré descanso.'),
  (64, 'Salmo 25:4-5', 'Señor, hazme conocer tus caminos; muéstrame tus sendas. Encamíname en tu verdad, ¡enséñame!'),
  (65, 'Proverbios 8:17', 'A los que me aman, les correspondo; a los que me buscan, me doy a conocer.'),
  (66, 'Romanos 8:38-39', 'Pues estoy convencido de que ni la muerte ni la vida, ni los ángeles ni los demonios, ni lo presente ni lo por venir, ni los poderes, ni lo alto ni lo profundo, ni cosa alguna en toda la creación podrá apartarnos del amor que Dios nos ha manifestado en Cristo Jesús nuestro Señor.'),
  (67, 'Mateo 11:29', 'Carguen con mi yugo y aprendan de mí, pues yo soy apacible y humilde de corazón, y encontrarán descanso para su alma.'),
  (68, 'Salmo 27:1', 'El Señor es mi luz y mi salvación; ¿a quién temeré? El Señor es el baluarte de mi vida; ¿quién podrá amedrentarme?'),
  (69, 'Mateo 16:24', 'Si alguien quiere ser mi discípulo, tiene que negarse a sí mismo, tomar su cruz y seguirme.'),
  (70, 'Romanos 10:9', 'Que si confiesas con tu boca que Jesús es el Señor y crees en tu corazón que Dios lo levantó de entre los muertos, serás salvo.'),
  (71, 'Proverbios 9:10', 'El comienzo de la sabiduría es el temor del Señor; conocer al Santo es tener discernimiento.'),
  (72, 'Mateo 17:20', 'Les aseguro que si tienen fe tan pequeña como un grano de mostaza, podrán decirle a esta montaña: “Trasládate de aquí para allá”, y se trasladará. Para ustedes nada será imposible.'),
  (73, 'Salmo 27:4', 'Una sola cosa le pido al Señor, y es lo único que persigo: habitar en la casa del Señor todos los días de mi vida.'),
  (74, 'Romanos 10:17', 'Así que la fe viene como resultado de oír el mensaje, y el mensaje que se oye es la palabra de Cristo.'),
  (75, 'Mateo 18:20', 'Porque donde dos o tres se reúnen en mi nombre, allí estoy yo en medio de ellos.'),
  (76, 'Salmo 27:14', 'Pon tu esperanza en el Señor; ten valor, cobra ánimo; ¡pon tu esperanza en el Señor!'),
  (77, 'Romanos 12:1', 'Por lo tanto, hermanos, tomando en cuenta la misericordia de Dios, les ruego que cada uno de ustedes, en adoración espiritual, ofrezca su cuerpo como sacrificio vivo, santo y agradable a Dios.'),
  (78, 'Proverbios 10:12', 'El odio es motivo de disensiones, pero el amor cubre todas las faltas.'),
  (79, 'Mateo 19:26', 'Para los hombres es imposible —aclaró Jesús, mirándolos fijamente—, mas para Dios todo es posible.'),
  (80, 'Salmo 28:7', 'El Señor es mi fuerza y mi escudo; mi corazón en él confía; de él recibo ayuda.'),
  (81, 'Romanos 12:2', 'No se amolden al mundo actual, sino sean transformados mediante la renovación de su mente.'),
  (82, 'Mateo 20:28', 'Así como el Hijo del hombre no vino para que le sirvan, sino para servir y para dar su vida en rescate por muchos.'),
  (83, 'Proverbios 10:19', 'El que mucho habla mucho yerra; el que es sabio refrena su lengua.'),
  (84, 'Salmo 30:5', 'Si por la noche hay llanto, por la mañana habrá gritos de alegría.'),
  (85, 'Mateo 22:37', '“Ama al Señor tu Dios con todo tu corazón, con todo tu ser y con toda tu mente”.'),
  (86, 'Romanos 12:10', 'Ámense los unos a los otros con amor fraternal, respetándose y honrándose mutuamente.'),
  (87, 'Mateo 22:39', 'El segundo se parece a este: “Ama a tu prójimo como a ti mismo”.'),
  (88, 'Salmo 31:24', 'Cobren ánimo y ármense de valor, todos los que en el Señor esperan.'),
  (89, 'Romanos 12:11', 'Nunca dejen de ser diligentes; antes bien, sirvan al Señor con el fervor que da el Espíritu.'),
  (90, 'Proverbios 11:2', 'Con el orgullo viene el oprobio; con la humildad, la sabiduría.'),
  (91, 'Mateo 24:35', 'El cielo y la tierra pasarán, pero mis palabras jamás pasarán.'),
  (92, 'Salmo 32:8', 'El Señor dice: «Yo te instruiré, yo te mostraré el camino que debes seguir; yo te daré consejos y velaré por ti».'),
  (93, 'Romanos 12:12', 'Alégrense en la esperanza, muestren paciencia en el sufrimiento, perseveren en la oración.'),
  (94, 'Mateo 25:40', 'El Rey les responderá: “Les aseguro que todo lo que hicieron por uno de mis hermanos, aun por el más pequeño, lo hicieron por mí”.'),
  (95, 'Salmo 33:12', 'Dichosa la nación cuyo Dios es el Señor, el pueblo que escogió por su heredad.'),
  (96, 'Proverbios 11:25', 'El que es generoso prospera; el que reanima será reanimado.'),
  (97, 'Mateo 26:41', 'Estén alerta y oren para que no caigan en tentación. El espíritu está dispuesto, pero el cuerpo es débil.'),
  (98, 'Romanos 12:21', 'No te dejes vencer por el mal; al contrario, vence el mal con el bien.'),
  (99, 'Salmo 34:1', 'Bendeciré al Señor en todo tiempo; mis labios siempre lo alabarán.'),
  (100, 'Mateo 28:19', 'Por tanto, vayan y hagan discípulos de todas las naciones, bautizándolos en el nombre del Padre y del Hijo y del Espíritu Santo.'),
  (101, 'Romanos 15:13', 'Que el Dios de la esperanza los llene de toda alegría y paz a ustedes que creen en él, para que rebosen de esperanza por el poder del Espíritu Santo.'),
  (102, 'Proverbios 12:15', 'Al necio le parece bien lo que emprende, pero el sabio atiende al consejo.'),
  (103, 'Mateo 28:20', 'Y les aseguro que estaré con ustedes siempre, hasta el fin del mundo.'),
  (104, 'Salmo 34:4', 'Busqué al Señor, y él me respondió; me libró de todos mis temores.'),
  (105, '1 Corintios 2:9', 'Ningún ojo ha visto, ningún oído ha escuchado, ninguna mente humana ha concebido lo que Dios ha preparado para quienes lo aman.'),
  (106, 'Marcos 1:35', 'Muy de madrugada, cuando todavía estaba oscuro, Jesús se levantó, salió de la casa y se fue a un lugar solitario, donde se puso a orar.'),
  (107, 'Salmo 34:8', 'Prueben y vean que el Señor es bueno; dichosos los que en él se refugian.'),
  (108, 'Proverbios 12:25', 'La angustia abate el corazón del hombre, pero una palabra amable lo alegra.'),
  (109, '1 Corintios 10:13', 'Fiel es Dios, y no permitirá que ustedes sean tentados más allá de lo que puedan aguantar.'),
  (110, 'Marcos 4:39', 'Él se levantó, reprendió al viento y ordenó al mar: —¡Silencio! ¡Cálmate! El viento se calmó y todo quedó completamente tranquilo.'),
  (111, 'Salmo 34:18', 'El Señor está cerca de los quebrantados de corazón, y salva a los de espíritu abatido.'),
  (112, 'Marcos 5:36', '—No tengas miedo; cree nada más.'),
  (113, '1 Corintios 10:31', 'En conclusión, ya sea que coman o beban o hagan cualquier otra cosa, háganlo todo para la gloria de Dios.'),
  (114, 'Proverbios 13:20', 'El que con sabios anda, sabio se vuelve; el que con necios se junta, saldrá mal parado.'),
  (115, 'Marcos 9:23', '—¿Cómo que si puedo? Para el que cree, todo es posible.'),
  (116, 'Salmo 37:4', 'Deléitate en el Señor, y él te concederá los deseos de tu corazón.'),
  (117, '1 Corintios 13:4', 'El amor es paciente, es bondadoso. El amor no es envidioso ni jactancioso ni orgulloso.'),
  (118, 'Marcos 9:24', '—¡Sí creo! —exclamó de inmediato el padre del muchacho—. ¡Ayúdame en mi poca fe!'),
  (119, 'Salmo 37:5', 'Encomienda al Señor tu camino; confía en él, y él actuará.'),
  (120, '1 Corintios 13:7', 'Todo lo disculpa, todo lo cree, todo lo espera, todo lo soporta.'),
  (121, 'Proverbios 14:29', 'El que es paciente muestra gran discernimiento; el que es agresivo muestra mucha insensatez.'),
  (122, 'Marcos 9:35', 'Si alguien quiere ser el primero, que sea el último de todos y el servidor de todos.'),
  (123, 'Salmo 37:7', 'Guarda silencio ante el Señor, y espera en él con paciencia.'),
  (124, 'Marcos 10:27', 'Para los hombres es imposible, pero no para Dios; de hecho, para Dios todo es posible.'),
  (125, '1 Corintios 13:13', 'Ahora, pues, permanecen estas tres virtudes: la fe, la esperanza y el amor. Pero la más excelente de ellas es el amor.'),
  (126, 'Proverbios 14:30', 'El corazón tranquilo da vida al cuerpo, pero la envidia corroe los huesos.'),
  (127, 'Salmo 37:23', 'El Señor afirma los pasos del hombre cuando le agrada su modo de vivir.'),
  (128, 'Marcos 10:45', 'Porque ni aun el Hijo del hombre vino para que le sirvan, sino para servir y para dar su vida en rescate por muchos.'),
  (129, '1 Corintios 15:58', 'Por lo tanto, mis queridos hermanos, manténganse firmes e inconmovibles, progresando siempre en la obra del Señor, conscientes de que su trabajo en el Señor no es en vano.'),
  (130, 'Marcos 11:24', 'Por eso les digo: Crean que ya han recibido todo lo que estén pidiendo en oración, y lo obtendrán.'),
  (131, 'Salmo 40:1', 'Puse mi esperanza en el Señor, y él inclinó su oído y escuchó mi clamor.'),
  (132, '1 Corintios 16:14', 'Hagan todo con amor.'),
  (133, 'Proverbios 15:1', 'La respuesta amable calma el enojo, pero la agresiva echa leña al fuego.'),
  (134, 'Marcos 11:25', 'Y cuando estén orando, si tienen algo contra alguien, perdónenlo, para que también su Padre que está en el cielo les perdone a ustedes sus pecados.'),
  (135, 'Salmo 42:1', 'Cual ciervo jadeante en busca del agua, así te busca, oh Dios, todo mi ser.'),
  (136, '2 Corintios 4:16', 'Por tanto, no nos desanimamos. Al contrario, aunque por fuera nos vamos desgastando, por dentro nos vamos renovando día tras día.'),
  (137, 'Marcos 12:30', 'Ama al Señor tu Dios con todo tu corazón, con toda tu alma, con toda tu mente y con todas tus fuerzas.'),
  (138, 'Salmo 42:11', '¿Por qué voy a inquietarme? ¿Por qué me voy a angustiar? En Dios pondré mi esperanza, y todavía lo alabaré.'),
  (139, 'Proverbios 15:13', 'El corazón alegre se refleja en el rostro, el corazón dolido deprime el espíritu.'),
  (140, 'Marcos 16:15', 'Vayan por todo el mundo y anuncien las buenas nuevas a toda criatura.'),
  (141, '2 Corintios 5:7', 'Vivimos por fe, no por vista.'),
  (142, 'Salmo 46:1', 'Dios es nuestro amparo y nuestra fortaleza, nuestra ayuda segura en momentos de angustia.'),
  (143, 'Lucas 1:37', 'Porque para Dios no hay nada imposible.'),
  (144, '2 Corintios 5:17', 'Por lo tanto, si alguno está en Cristo, es una nueva creación. ¡Lo viejo ha pasado, ha llegado ya lo nuevo!'),
  (145, 'Proverbios 15:22', 'Cuando falta el consejo, fracasan los planes; cuando abunda el consejo, prosperan.'),
  (146, 'Lucas 1:45', '¡Dichosa tú que has creído, porque lo que el Señor te ha dicho se cumplirá!'),
  (147, 'Salmo 46:10', 'Quédense quietos, reconozcan que yo soy Dios.'),
  (148, '2 Corintios 9:7', 'Cada uno debe dar según lo que haya decidido en su corazón, no de mala gana ni por obligación, porque Dios ama al que da con alegría.'),
  (149, 'Lucas 1:46-47', 'Mi alma glorifica al Señor, y mi espíritu se regocija en Dios mi Salvador.'),
  (150, 'Salmo 51:10', 'Crea en mí, oh Dios, un corazón limpio, y renueva la firmeza de mi espíritu.'),
  (151, 'Proverbios 15:23', 'Es muy grato dar la respuesta adecuada, y más grato aún cuando es oportuna.'),
  (152, 'Lucas 2:10-11', 'No tengan miedo. Miren que les traigo buenas noticias que serán motivo de mucha alegría para todo el pueblo. Hoy les ha nacido en la ciudad de David un Salvador, que es Cristo el Señor.'),
  (153, '2 Corintios 12:9', 'Te basta con mi gracia, pues mi poder se perfecciona en la debilidad.'),
  (154, 'Salmo 55:22', 'Encomienda al Señor tus afanes, y él te sostendrá; no permitirá que el justo caiga y quede abatido para siempre.'),
  (155, 'Lucas 2:14', 'Gloria a Dios en las alturas, y en la tierra paz a los que gozan de su buena voluntad.'),
  (156, 'Gálatas 2:20', 'He sido crucificado con Cristo, y ya no vivo yo, sino que Cristo vive en mí.'),
  (157, 'Proverbios 16:3', 'Pon en manos del Señor todas tus obras, y tus proyectos se cumplirán.'),
  (158, 'Lucas 2:52', 'Jesús siguió creciendo en sabiduría y estatura, y cada vez más gozaba del favor de Dios y de toda la gente.'),
  (159, 'Salmo 56:3', 'Cuando siento miedo, pongo en ti mi confianza.'),
  (160, 'Gálatas 5:13', 'Les hablo así, hermanos, porque ustedes han sido llamados a ser libres; pero no se valgan de esa libertad para dar rienda suelta a sus pasiones. Más bien sírvanse unos a otros con amor.'),
  (161, 'Lucas 4:18', 'El Espíritu del Señor está sobre mí, por cuanto me ha ungido para anunciar buenas nuevas a los pobres.'),
  (162, 'Salmo 59:16', 'Pero yo le cantaré a tu poder, y por la mañana alabaré tu amor; porque tú eres mi protector, mi refugio en momentos de angustia.'),
  (163, 'Gálatas 5:22-23', 'En cambio, el fruto del Espíritu es amor, alegría, paz, paciencia, amabilidad, bondad, fidelidad, humildad y dominio propio.'),
  (164, 'Proverbios 16:9', 'El corazón del hombre traza su rumbo, pero sus pasos los dirige el Señor.'),
  (165, 'Lucas 5:16', 'Él, por su parte, solía retirarse a lugares solitarios para orar.'),
  (166, 'Salmo 61:2', 'Desde los confines de la tierra te invoco, pues mi corazón desfallece; llévame a una roca donde esté yo a salvo.'),
  (167, 'Lucas 6:27-28', 'Amen a sus enemigos, hagan bien a quienes los odian, bendigan a quienes los maldicen, oren por quienes los maltratan.'),
  (168, 'Gálatas 6:2', 'Ayúdense unos a otros a llevar sus cargas, y así cumplirán la ley de Cristo.'),
  (169, 'Salmo 62:1', 'Solo en Dios halla descanso mi alma; de él viene mi salvación.'),
  (170, 'Proverbios 16:18', 'Al orgullo le sigue la destrucción; a la altanería, el fracaso.'),
  (171, 'Lucas 6:31', 'Traten a los demás tal y como quieren que ellos los traten a ustedes.'),
  (172, 'Gálatas 6:9', 'No nos cansemos de hacer el bien, porque a su debido tiempo cosecharemos si no nos damos por vencidos.'),
  (173, 'Lucas 6:36', 'Sean compasivos, así como su Padre es compasivo.'),
  (174, 'Salmo 62:8', 'Confía en él, pueblo mío, en todo momento; ábrele tu corazón cuando estés ante él. ¡Dios es nuestro refugio!'),
  (175, 'Efesios 2:8', 'Porque por gracia ustedes han sido salvados mediante la fe; esto no procede de ustedes, sino que es el regalo de Dios.'),
  (176, 'Proverbios 16:24', 'Panal de miel son las palabras amables: endulzan la vida y dan salud al cuerpo.'),
  (177, 'Lucas 6:37', 'No juzguen, y no se les juzgará. No condenen, y no se les condenará. Perdonen, y se les perdonará.'),
  (178, 'Salmo 63:1', 'Oh Dios, tú eres mi Dios; yo te busco intensamente.'),
  (179, 'Lucas 6:38', 'Den, y se les dará: se les echará en el regazo una medida llena, apretada, sacudida y desbordante. Porque con la medida que midan a otros, se les medirá a ustedes.'),
  (180, 'Efesios 2:10', 'Porque somos hechura de Dios, creados en Cristo Jesús para buenas obras, las cuales Dios dispuso de antemano a fin de que las pongamos en práctica.'),
  (181, 'Salmo 63:3', 'Tu amor es mejor que la vida; por eso mis labios te alabarán.'),
  (182, 'Proverbios 16:32', 'Más vale ser paciente que valiente; más vale dominarse a sí mismo que conquistar ciudades.'),
  (183, 'Lucas 9:23', 'Si alguien quiere ser mi discípulo, que se niegue a sí mismo, lleve su cruz cada día y me siga.'),
  (184, 'Efesios 3:20', 'Al que puede hacer muchísimo más que todo lo que podamos imaginarnos o pedir, por el poder que obra eficazmente en nosotros.'),
  (185, 'Lucas 10:27', '“Ama al Señor tu Dios con todo tu corazón, con todo tu ser, con todas tus fuerzas y con toda tu mente”, y: “Ama a tu prójimo como a ti mismo”.'),
  (186, 'Salmo 66:20', '¡Bendito sea Dios, que no rechazó mi plegaria ni me negó su amor!'),
  (187, 'Efesios 4:2', 'Siempre humildes y amables, pacientes, tolerantes unos con otros en amor.'),
  (188, 'Lucas 10:41-42', 'Marta, Marta, estás inquieta y preocupada por muchas cosas, pero solo una es necesaria. María ha escogido la mejor, y nadie se la quitará.'),
  (189, 'Proverbios 17:17', 'En todo tiempo ama el amigo; para ayudar en la adversidad nació el hermano.'),
  (190, 'Salmo 68:19', 'Bendito sea el Señor, nuestro Dios y Salvador, que día tras día sobrelleva nuestras cargas.'),
  (191, 'Efesios 4:32', 'Más bien, sean bondadosos y compasivos unos con otros, y perdónense mutuamente, así como Dios los perdonó a ustedes en Cristo.'),
  (192, 'Lucas 11:9', 'Así que yo les digo: Pidan, y se les dará; busquen, y encontrarán; llamen, y se les abrirá la puerta.'),
  (193, 'Salmo 71:5', 'Tú, Soberano Señor, has sido mi esperanza; en ti he confiado desde mi juventud.'),
  (194, 'Lucas 11:28', 'Dichosos más bien quienes oyen la palabra de Dios y la obedecen.'),
  (195, 'Proverbios 17:22', 'Gran remedio es el corazón alegre, pero el ánimo decaído seca los huesos.'),
  (196, 'Efesios 6:10', 'Por último, fortalézcanse con el gran poder del Señor.'),
  (197, 'Salmo 73:26', 'Podrán desfallecer mi cuerpo y mi espíritu, pero Dios fortalece mi corazón; él es mi herencia eterna.'),
  (198, 'Lucas 12:7', 'Así mismo sucede con ustedes: aun los cabellos de su cabeza están contados. No tengan miedo; ustedes valen más que muchos gorriones.'),
  (199, 'Filipenses 1:6', 'Estoy convencido de esto: el que comenzó tan buena obra en ustedes la irá perfeccionando hasta el día de Cristo Jesús.'),
  (200, 'Lucas 12:15', '¡Tengan cuidado! Absténganse de toda avaricia; la vida de una persona no depende de la abundancia de sus bienes.'),
  (201, 'Proverbios 18:10', 'Torre inexpugnable es el nombre del Señor; a ella corren los justos y se ponen a salvo.'),
  (202, 'Salmo 84:10', 'Vale más pasar un día en tus atrios que mil fuera de ellos.'),
  (203, 'Filipenses 2:3', 'No hagan nada por egoísmo o vanidad; más bien, con humildad consideren a los demás como superiores a ustedes mismos.'),
  (204, 'Lucas 12:32', 'No tengan miedo, mi rebaño pequeño, porque es la buena voluntad del Padre darles el reino.'),
  (205, 'Salmo 84:11', 'El Señor Dios es sol y escudo; Dios nos concede honor y gloria. El Señor brinda generosamente su bondad a los que se conducen sin tacha.'),
  (206, 'Lucas 15:7', 'Les digo que así es también en el cielo: habrá más alegría por un solo pecador que se arrepienta que por noventa y nueve justos que no necesitan arrepentirse.'),
  (207, 'Proverbios 18:21', 'En la lengua hay poder de vida y muerte; quienes la aman comerán de su fruto.'),
  (208, 'Filipenses 2:4', 'Cada uno debe velar no solo por sus propios intereses, sino también por los intereses de los demás.'),
  (209, 'Salmo 86:5', 'Tú, Señor, eres bueno y perdonador; grande es tu amor por todos los que te invocan.'),
  (210, 'Lucas 15:20', 'Todavía estaba lejos cuando su padre lo vio y se compadeció de él; salió corriendo a su encuentro, lo abrazó y lo besó.'),
  (211, 'Filipenses 3:13-14', 'Una cosa hago: olvidando lo que queda atrás y esforzándome por alcanzar lo que está delante, sigo avanzando hacia la meta para ganar el premio que Dios ofrece mediante su llamamiento celestial en Cristo Jesús.'),
  (212, 'Salmo 90:12', 'Enséñanos a contar bien nuestros días, para que nuestro corazón adquiera sabiduría.'),
  (213, 'Lucas 16:10', 'El que es honrado en lo poco también lo será en lo mucho; y el que no es íntegro en lo poco tampoco lo será en lo mucho.'),
  (214, 'Proverbios 18:24', 'Hay amigos que llevan a la ruina, y hay amigos más fieles que un hermano.'),
  (215, 'Filipenses 4:4', 'Alégrense siempre en el Señor. Insisto: ¡Alégrense!'),
  (216, 'Lucas 18:1', 'Jesús les contó a sus discípulos una parábola para mostrarles que debían orar siempre, sin desanimarse.'),
  (217, 'Salmo 91:1', 'El que habita al abrigo del Altísimo se acoge a la sombra del Todopoderoso.'),
  (218, 'Filipenses 4:6', 'No se inquieten por nada; más bien, en toda ocasión, con oración y ruego, presenten sus peticiones a Dios y denle gracias.'),
  (219, 'Lucas 18:27', 'Lo que es imposible para los hombres es posible para Dios.'),
  (220, 'Proverbios 19:11', 'El buen juicio hace al hombre paciente; su gloria es pasar por alto la ofensa.'),
  (221, 'Salmo 91:2', 'Yo le digo al Señor: «Tú eres mi refugio, mi fortaleza, el Dios en quien confío».'),
  (222, 'Lucas 19:10', 'Porque el Hijo del hombre vino a buscar y a salvar lo que se había perdido.'),
  (223, 'Filipenses 4:7', 'Y la paz de Dios, que sobrepasa todo entendimiento, cuidará sus corazones y sus pensamientos en Cristo Jesús.'),
  (224, 'Salmo 91:11', 'Porque él ordenará que sus ángeles te cuiden en todos tus caminos.'),
  (225, 'Lucas 21:33', 'El cielo y la tierra pasarán, pero mis palabras jamás pasarán.'),
  (226, 'Proverbios 19:17', 'Servir al pobre es hacerle un préstamo al Señor; Dios pagará esas buenas acciones.'),
  (227, 'Filipenses 4:8', 'Consideren bien todo lo verdadero, todo lo respetable, todo lo justo, todo lo puro, todo lo amable, todo lo digno de admiración, en fin, todo lo que sea excelente o merezca elogio.'),
  (228, 'Lucas 22:27', 'Pero yo estoy entre ustedes como uno que sirve.'),
  (229, 'Salmo 92:1', '¡Cuán bueno, Señor, es darte gracias y entonar, oh Altísimo, salmos a tu nombre!'),
  (230, 'Filipenses 4:13', 'Todo lo puedo en Cristo que me fortalece.'),
  (231, 'Lucas 22:42', 'Padre, si quieres, no me hagas beber este trago amargo; pero no se cumpla mi voluntad, sino la tuya.'),
  (232, 'Proverbios 19:20', 'Escucha el consejo, acepta la corrección, y llegarás a ser sabio.'),
  (233, 'Salmo 94:19', 'Cuando en mí la angustia iba en aumento, tu consuelo llenaba mi alma de alegría.'),
  (234, 'Lucas 24:6', 'No está aquí; ¡ha resucitado!'),
  (235, 'Filipenses 4:19', 'Así que mi Dios les proveerá de todo lo que necesiten, conforme a las gloriosas riquezas que tiene en Cristo Jesús.'),
  (236, 'Salmo 95:1', 'Vengan, cantemos con júbilo al Señor; aclamemos a la roca de nuestra salvación.'),
  (237, 'Juan 1:1', 'En el principio ya existía el Verbo, y el Verbo estaba con Dios, y el Verbo era Dios.'),
  (238, 'Proverbios 19:21', 'El corazón humano genera muchos proyectos, pero al final prevalecen los designios del Señor.'),
  (239, 'Colosenses 3:2', 'Concentren su atención en las cosas de arriba, no en las de la tierra.'),
  (240, 'Salmo 95:6', 'Vengan, postrémonos reverentes, doblemos la rodilla ante el Señor nuestro Hacedor.'),
  (241, 'Juan 1:4-5', 'En él estaba la vida, y la vida era la luz de la humanidad. Esta luz resplandece en las tinieblas, y las tinieblas no han podido extinguirla.'),
  (242, 'Colosenses 3:13', 'De modo que se toleren unos a otros y se perdonen si alguno tiene queja contra otro. Así como el Señor los perdonó, perdonen también ustedes.'),
  (243, 'Juan 1:12', 'Mas a cuantos lo recibieron, a los que creen en su nombre, les dio el derecho de ser hijos de Dios.'),
  (244, 'Salmo 96:1', 'Canten al Señor un cántico nuevo; canten al Señor, habitantes de toda la tierra.'),
  (245, 'Proverbios 20:7', 'Justo es quien lleva una vida sin tacha; ¡dichosos los hijos que sigan su ejemplo!'),
  (246, 'Colosenses 3:14', 'Por encima de todo, vístanse de amor, que es el vínculo perfecto.'),
  (247, 'Juan 1:14', 'Y el Verbo se hizo hombre y habitó entre nosotros. Y hemos contemplado su gloria, la gloria que corresponde al Hijo unigénito del Padre, lleno de gracia y de verdad.'),
  (248, 'Salmo 100:1-2', 'Aclamen alegres al Señor, habitantes de toda la tierra; adoren al Señor con regocijo. Preséntense ante él con cánticos de júbilo.'),
  (249, 'Juan 1:16', 'De su plenitud todos hemos recibido gracia sobre gracia.'),
  (250, 'Proverbios 21:21', 'El que va tras la justicia y el amor halla vida, prosperidad y honra.'),
  (251, 'Colosenses 3:23', 'Hagan lo que hagan, trabajen de buena gana, como para el Señor y no como para nadie en este mundo.'),
  (252, 'Salmo 100:4', 'Entren por sus puertas con acción de gracias; vengan a sus atrios con himnos de alabanza; denle gracias, alaben su nombre.'),
  (253, 'Juan 3:16', 'Porque tanto amó Dios al mundo que dio a su Hijo unigénito, para que todo el que cree en él no se pierda, sino que tenga vida eterna.'),
  (254, '1 Tesalonicenses 5:16-18', 'Estén siempre alegres, oren sin cesar, den gracias a Dios en toda situación, porque esta es su voluntad para ustedes en Cristo Jesús.'),
  (255, 'Salmo 100:5', 'Porque el Señor es bueno y su gran amor es eterno; su fidelidad permanece para siempre.'),
  (256, 'Juan 3:17', 'Dios no envió a su Hijo al mundo para condenar al mundo, sino para salvarlo por medio de él.'),
  (257, 'Proverbios 22:1', 'Vale más la buena fama que las muchas riquezas, y más que oro y plata, la buena reputación.'),
  (258, '2 Timoteo 1:7', 'Pues Dios no nos ha dado un espíritu de timidez, sino de poder, de amor y de dominio propio.'),
  (259, 'Juan 3:30', 'A él le toca crecer, y a mí menguar.'),
  (260, 'Salmo 103:1-2', 'Alaba, alma mía, al Señor; alabe todo mi ser su santo nombre. Alaba, alma mía, al Señor, y no olvides ninguno de sus beneficios.'),
  (261, 'Juan 4:14', 'El que beba del agua que yo le daré no volverá a tener sed jamás, sino que dentro de él esa agua se convertirá en un manantial del que brotará vida eterna.'),
  (262, '2 Timoteo 3:16', 'Toda la Escritura es inspirada por Dios y útil para enseñar, para reprender, para corregir y para instruir en la justicia.'),
  (263, 'Proverbios 22:6', 'Instruye al niño en el camino correcto, y aun en su vejez no lo abandonará.'),
  (264, 'Salmo 103:8', 'El Señor es clemente y compasivo, lento para la ira y grande en amor.'),
  (265, 'Juan 4:24', 'Dios es espíritu, y quienes lo adoran deben hacerlo en espíritu y en verdad.'),
  (266, '2 Timoteo 4:7', 'He peleado la buena batalla, he terminado la carrera, me he mantenido en la fe.'),
  (267, 'Salmo 103:12', 'Tan lejos de nosotros echó nuestras transgresiones como lejos del oriente está el occidente.'),
  (268, 'Juan 5:24', 'Ciertamente les aseguro que el que oye mi palabra y cree al que me envió tiene vida eterna y no será juzgado, sino que ha pasado de la muerte a la vida.'),
  (269, 'Proverbios 22:9', 'El que es generoso será bendecido, pues comparte su comida con los pobres.'),
  (270, 'Hebreos 4:12', 'Ciertamente, la palabra de Dios es viva y poderosa, y más cortante que cualquier espada de dos filos.'),
  (271, 'Juan 6:35', 'Yo soy el pan de vida —declaró Jesús—. El que a mí viene nunca pasará hambre, y el que en mí cree nunca más volverá a tener sed.'),
  (272, 'Salmo 107:1', 'Den gracias al Señor, porque él es bueno; su gran amor perdura para siempre.'),
  (273, 'Hebreos 4:16', 'Así que acerquémonos confiadamente al trono de la gracia para recibir misericordia y hallar la gracia que nos ayude en el momento que más la necesitemos.'),
  (274, 'Juan 6:37', 'Todos los que el Padre me da vendrán a mí; y al que a mí viene, no lo rechazo.'),
  (275, 'Proverbios 22:29', '¿Has visto a alguien diligente en su trabajo? Se codeará con reyes, y nunca será un don nadie.'),
  (276, 'Salmo 112:7', 'No temerá recibir malas noticias; su corazón estará firme, confiado en el Señor.'),
  (277, 'Juan 6:68', 'Señor —contestó Simón Pedro—, ¿a quién iremos? Tú tienes palabras de vida eterna.'),
  (278, 'Hebreos 10:24', 'Preocupémonos los unos por los otros, a fin de estimularnos al amor y a las buenas obras.'),
  (279, 'Salmo 113:3', 'Desde la salida del sol hasta su ocaso, sea alabado el nombre del Señor.'),
  (280, 'Juan 7:38', 'De aquel que cree en mí, como dice la Escritura, brotarán ríos de agua viva.'),
  (281, 'Proverbios 23:12', 'Aplica tu corazón a la disciplina y tus oídos a las palabras del conocimiento.'),
  (282, 'Hebreos 11:1', 'Ahora bien, la fe es la garantía de lo que se espera, la certeza de lo que no se ve.'),
  (283, 'Salmo 116:1', 'Yo amo al Señor porque él escucha mi voz suplicante.'),
  (284, 'Juan 8:12', 'Yo soy la luz del mundo. El que me sigue no andará en tinieblas, sino que tendrá la luz de la vida.'),
  (285, 'Hebreos 11:6', 'En realidad, sin fe es imposible agradar a Dios, ya que cualquiera que se acerca a Dios tiene que creer que él existe y que recompensa a quienes lo buscan.'),
  (286, 'Juan 8:31-32', 'Si se mantienen fieles a mis enseñanzas, serán realmente mis discípulos; y conocerán la verdad, y la verdad los hará libres.'),
  (287, 'Salmo 118:6', 'El Señor está conmigo, y no tengo miedo; ¿qué me puede hacer un simple mortal?'),
  (288, 'Proverbios 24:16', 'Porque siete veces podrá caer el justo, pero otras tantas se levantará.'),
  (289, 'Juan 8:36', 'Así que si el Hijo los libera, serán ustedes verdaderamente libres.'),
  (290, 'Hebreos 12:2', 'Fijemos la mirada en Jesús, el iniciador y perfeccionador de nuestra fe.'),
  (291, 'Salmo 118:24', 'Este es el día en que el Señor actuó; regocijémonos y alegrémonos en él.'),
  (292, 'Juan 10:10', 'El ladrón no viene más que a robar, matar y destruir; yo he venido para que tengan vida, y la tengan en abundancia.'),
  (293, 'Proverbios 25:11', 'Como naranjas de oro con incrustaciones de plata son las palabras dichas a tiempo.'),
  (294, 'Hebreos 13:5', 'Dios ha dicho: «Nunca te dejaré; jamás te abandonaré».'),
  (295, 'Salmo 119:11', 'En mi corazón atesoro tus dichos para no pecar contra ti.'),
  (296, 'Juan 10:11', 'Yo soy el buen pastor. El buen pastor da su vida por las ovejas.'),
  (297, 'Hebreos 13:8', 'Jesucristo es el mismo ayer y hoy y por los siglos.'),
  (298, 'Salmo 119:18', 'Ábreme los ojos, para que contemple las maravillas de tu ley.'),
  (299, 'Juan 10:27-28', 'Mis ovejas oyen mi voz; yo las conozco y ellas me siguen. Yo les doy vida eterna, y nunca perecerán, ni nadie podrá arrebatármelas de la mano.'),
  (300, 'Proverbios 27:1', 'No te jactes del día de mañana, porque no sabes lo que el día traerá.'),
  (301, 'Santiago 1:5', 'Si a alguno de ustedes le falta sabiduría, pídasela a Dios, y él se la dará, pues Dios da a todos generosamente sin menospreciar a nadie.'),
  (302, 'Juan 11:25', 'Yo soy la resurrección y la vida. El que cree en mí vivirá, aunque muera.'),
  (303, 'Salmo 119:50', 'Este es mi consuelo en medio del dolor: que tu promesa me da vida.'),
  (304, 'Juan 11:40', '¿No te dije que si crees verás la gloria de Dios?'),
  (305, 'Santiago 1:19', 'Todos deben estar listos para escuchar, y ser lentos para hablar y para enojarse.'),
  (306, 'Proverbios 27:2', 'No te jactes de ti mismo; que sean otros los que te alaben.'),
  (307, 'Salmo 119:105', 'Tu palabra es una lámpara a mis pies; es una luz en mi sendero.'),
  (308, 'Juan 12:26', 'Quien quiera servirme, debe seguirme; y donde yo esté, allí también estará mi siervo. A quien me sirva, mi Padre lo honrará.'),
  (309, 'Santiago 1:22', 'No se contenten solo con escuchar la palabra, pues así se engañan ustedes mismos. Llévenla a la práctica.'),
  (310, 'Salmo 119:114', 'Tú eres mi escondite y mi escudo; en tu palabra he puesto mi esperanza.'),
  (311, 'Juan 13:14', 'Pues, si yo, el Señor y el Maestro, les he lavado los pies, también ustedes deben lavarse los pies los unos a los otros.'),
  (312, 'Proverbios 27:17', 'El hierro se afila con el hierro, y el hombre en el trato con el hombre.'),
  (313, 'Santiago 4:8', 'Acérquense a Dios, y él se acercará a ustedes.'),
  (314, 'Juan 13:34', 'Este mandamiento nuevo les doy: que se amen los unos a los otros. Así como yo los he amado, también ustedes deben amarse los unos a los otros.'),
  (315, 'Salmo 121:1-2', 'A las montañas levanto mis ojos; ¿de dónde ha de venir mi ayuda? Mi ayuda proviene del Señor, creador del cielo y de la tierra.'),
  (316, 'Juan 13:35', 'De este modo todos sabrán que son mis discípulos, si se aman los unos a los otros.'),
  (317, 'Santiago 4:10', 'Humíllense delante del Señor, y él los exaltará.'),
  (318, 'Salmo 121:8', 'El Señor te cuidará en el hogar y en el camino, desde ahora y para siempre.'),
  (319, 'Proverbios 28:13', 'Quien encubre su pecado jamás prospera; quien lo confiesa y lo deja, halla perdón.'),
  (320, 'Juan 14:1', 'No se angustien. Confíen en Dios, y confíen también en mí.'),
  (321, '1 Pedro 4:10', 'Cada uno ponga al servicio de los demás el don que haya recibido, administrando fielmente la gracia de Dios en sus diversas formas.'),
  (322, 'Salmo 126:3', 'Sí, el Señor ha hecho grandes cosas por nosotros, y eso nos llena de alegría.'),
  (323, 'Juan 14:6', 'Yo soy el camino, la verdad y la vida —le contestó Jesús—. Nadie llega al Padre sino por mí.'),
  (324, 'Proverbios 28:20', 'El hombre fiel recibirá muchas bendiciones.'),
  (325, '1 Pedro 5:7', 'Depositen en él toda ansiedad, porque él cuida de ustedes.'),
  (326, 'Salmo 127:1', 'Si el Señor no edifica la casa, en vano se esfuerzan los albañiles.'),
  (327, 'Juan 14:15', 'Si ustedes me aman, obedecerán mis mandamientos.'),
  (328, '2 Pedro 3:18', 'Más bien, crezcan en la gracia y en el conocimiento de nuestro Señor y Salvador Jesucristo.'),
  (329, 'Juan 14:26', 'Pero el Consolador, el Espíritu Santo, a quien el Padre enviará en mi nombre, les enseñará todas las cosas y les hará recordar todo lo que les he dicho.'),
  (330, 'Salmo 133:1', '¡Cuán bueno y cuán agradable es que los hermanos convivan en armonía!'),
  (331, 'Proverbios 29:25', 'Temer a los hombres resulta una trampa, pero el que confía en el Señor sale bien librado.'),
  (332, 'Juan 14:27', 'La paz les dejo; mi paz les doy. Yo no se la doy a ustedes como la da el mundo. No se angustien ni se acobarden.'),
  (333, '1 Juan 1:9', 'Si confesamos nuestros pecados, Dios, que es fiel y justo, nos los perdonará y nos limpiará de toda maldad.'),
  (334, 'Salmo 136:1', 'Den gracias al Señor, porque él es bueno; su gran amor perdura para siempre.'),
  (335, 'Juan 15:5', 'Yo soy la vid y ustedes son las ramas. El que permanece en mí, como yo en él, dará mucho fruto; separados de mí no pueden ustedes hacer nada.'),
  (336, 'Proverbios 30:5', 'Toda palabra de Dios es digna de crédito; Dios protege a los que en él buscan refugio.'),
  (337, '1 Juan 3:1', '¡Fíjense qué gran amor nos ha dado el Padre, que se nos llame hijos de Dios! ¡Y lo somos!'),
  (338, 'Salmo 138:8', 'El Señor cumplirá en mí su propósito. Tu gran amor, Señor, perdura para siempre.'),
  (339, 'Juan 15:7', 'Si permanecen en mí y mis palabras permanecen en ustedes, pidan lo que quieran, y se les concederá.'),
  (340, '1 Juan 3:18', 'Queridos hijos, no amemos de palabra ni de labios para afuera, sino con hechos y de verdad.'),
  (341, 'Salmo 139:14', '¡Te alabo porque soy una creación admirable! ¡Tus obras son maravillosas, y esto lo sé muy bien!'),
  (342, 'Juan 15:9', 'Así como el Padre me ha amado a mí, también yo los he amado a ustedes. Permanezcan en mi amor.'),
  (343, 'Proverbios 31:8', '¡Levanta la voz por los que no tienen voz! ¡Defiende los derechos de los desposeídos!'),
  (344, 'Juan 15:12', 'Y este es mi mandamiento: que se amen los unos a los otros, como yo los he amado.'),
  (345, '1 Juan 4:7', 'Queridos hermanos, amémonos los unos a los otros, porque el amor viene de Dios.'),
  (346, 'Salmo 139:23-24', 'Examíname, oh Dios, y sondea mi corazón; ponme a prueba y sondea mis pensamientos. Fíjate si voy por mal camino, y guíame por el camino eterno.'),
  (347, 'Juan 15:13', 'Nadie tiene amor más grande que el dar la vida por sus amigos.'),
  (348, '1 Juan 4:18', 'En el amor no hay temor, sino que el amor perfecto echa fuera el temor.'),
  (349, 'Proverbios 31:25', 'Se reviste de fuerza y dignidad, y afronta segura el porvenir.'),
  (350, 'Salmo 143:8', 'Por la mañana hazme saber de tu gran amor, porque en ti he puesto mi confianza.'),
  (351, 'Juan 15:16', 'No me escogieron ustedes a mí, sino que yo los escogí a ustedes y los comisioné para que vayan y den fruto, un fruto que perdure.'),
  (352, '1 Juan 4:19', 'Nosotros amamos porque él nos amó primero.'),
  (353, 'Salmo 143:10', 'Enséñame a hacer tu voluntad, porque tú eres mi Dios.'),
  (354, 'Juan 16:24', 'Hasta ahora no han pedido nada en mi nombre. Pidan y recibirán, para que su alegría sea completa.'),
  (355, 'Proverbios 31:26', 'Cuando habla, lo hace con sabiduría; cuando instruye, lo hace con amor.'),
  (356, '1 Juan 5:4', 'Porque todo el que ha nacido de Dios vence al mundo. Esta es la victoria que vence al mundo: nuestra fe.'),
  (357, 'Juan 16:33', 'Yo les he dicho estas cosas para que en mí hallen paz. En este mundo afrontarán aflicciones, pero ¡anímense! Yo he vencido al mundo.'),
  (358, 'Salmo 145:9', 'El Señor es bueno con todos; él se compadece de toda su creación.'),
  (359, 'Juan 17:17', 'Santifícalos en la verdad; tu palabra es la verdad.'),
  (360, 'Apocalipsis 3:20', 'Mira que estoy a la puerta y llamo. Si alguno oye mi voz y abre la puerta, entraré, y cenaré con él, y él conmigo.'),
  (361, 'Salmo 145:18', 'El Señor está cerca de quienes lo invocan, de quienes lo invocan en verdad.'),
  (362, 'Proverbios 31:30', 'Engañoso es el encanto y pasajera la belleza; la mujer que teme al Señor es digna de alabanza.'),
  (363, 'Juan 20:21', '¡La paz sea con ustedes! Como el Padre me envió a mí, así yo los envío a ustedes.'),
  (364, 'Apocalipsis 21:4', 'Él les enjugará toda lágrima de los ojos. Ya no habrá muerte, ni llanto, ni lamento ni dolor.'),
  (365, 'Salmo 147:3', 'Él restaura a los abatidos y cubre con vendas sus heridas.'),
  (366, 'Juan 20:29', 'Dichosos los que no han visto y sin embargo creen.'),
  (367, 'Proverbios 11:30', 'El fruto de la justicia es árbol de vida, y el que gana almas es sabio.'),
  (368, 'Apocalipsis 21:5', 'El que estaba sentado en el trono dijo: «¡Yo hago nuevas todas las cosas!».'),
  (369, 'Salmo 150:6', '¡Que todo lo que respira alabe al Señor! ¡Aleluya! ¡Alabado sea el Señor!'),
  (370, 'Juan 21:17', 'Señor, tú lo sabes todo; tú sabes que te quiero. —Apacienta mis ovejas —le dijo Jesús.')
